(function(){
'use strict';
if('scrollRestoration' in history)history.scrollRestoration='manual';
const PRODUCTS=window.LG_FULL_CATALOG_DATA||window.LG_CATALOG_DATA, CATEGORIES=window.LG_FULL_CATEGORIES||window.LG_CATEGORIES, ASSETS=window.LG_ASSETS;
const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('vi-VN').format(n)+'đ';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',back:'<path d="m14 5-7 7 7 7"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',package:'<path d="m3 7 9-4 9 4v12l-9 3-9-3ZM3 7l9 4 9-4M12 11v11M7 5l10 4v5"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',bag:'<path d="M5 7h14l1 14H4ZM8 8V6a4 4 0 0 1 8 0v2"/>',heart:'<path d="M20.5 5.5a5 5 0 0 0-7.1 0L12 7l-1.4-1.5a5 5 0 0 0-7.1 7.1L12 21l8.5-8.4a5 5 0 0 0 0-7.1Z"/>',filter:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2" fill="white"/><circle cx="16" cy="12" r="2" fill="white"/><circle cx="10" cy="18" r="2" fill="white"/>',check:'<path d="m5 12 4 4L20 5"/>',shield:'<path d="m12 2 8 3v7c0 5-8 10-8 10S4 17 4 12V5Z"/><path d="m8 11 3 3 5-5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 11h18m-10 5 2 2 4-4"/>',tool:'<path d="M14 3a6 6 0 0 0-7 7L3 18a2 2 0 0 0 3 3l8-8a6 6 0 0 0 7-7l-4 4-3-3Z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',phone:'<path d="m5 3 4 1 1 5-3 2a12 12 0 0 0 6 6l2-3 5 1 1 4c-1 5-8 1-12-3S1 4 5 3Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',location:'<path d="M19 9c0 6-7 13-7 13S5 15 5 9a7 7 0 0 1 14 0Z"/><circle cx="12" cy="9" r="2"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',receipt:'<path d="M5 3h14v19l-3-2-4 2-4-2-3 2ZM8 8h8M8 12h8M8 16h4"/>',chat:'<path d="M21 11a9 9 0 0 1-9 9H3l2-5a9 9 0 1 1 16-4Z"/><path d="M8 10h8M8 14h5"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[k]||paths.grid}</svg>`;
const byId=id=>PRODUCTS.find(p=>p.id===id)||null;
const cat=id=>CATEGORIES.find(c=>c.id===id);
const statusLabel=p=>({'out-of-stock':'Tạm hết hàng','end-of-life':'Ngừng kinh doanh','pending-update':'Sắp cập nhật'}[p.availability]||'Tạm chưa nhận đơn hàng');
let storedConsultations=[];try{const rows=JSON.parse(localStorage.getItem('lgs-consultations-v1')||'[]');if(Array.isArray(rows))storedConsultations=rows.filter(r=>r&&typeof r.ref==='string'&&typeof r.model==='string'&&PRODUCTS.some(p=>p.id===r.productId));}catch{}
let stored={};try{stored=JSON.parse(localStorage.getItem('lgs-preview-v2')||'{}')}catch{}
const state={saved:(Array.isArray(stored.saved)?stored.saved:[]).filter(id=>PRODUCTS.some(p=>p.id===id)),cart:(Array.isArray(stored.cart)?stored.cart:[]).filter(x=>x&&PRODUCTS.some(p=>p.id===x.id)),requests:(Array.isArray(stored.requests)?stored.requests:[]).filter(r=>r&&[12,24,36].includes(r.plan)&&['monthly','buy'].includes(r.mode)&&PRODUCTS.some(p=>p.id===r.id)),consultations:storedConsultations,consultation:{productId:'',name:'',phone:'',email:'',errors:{},submitting:false,success:null},consultBack:'/products',campaign:0,category:'all',query:'',sort:'recommended',filters:{budget:'all',capacity:'all',style:'all',maxWidth:'all'},draft:null,plan:36,mode:'monthly',gallery:0,productPreferences:{},previous:'#/products',scrolls:{},form:{name:'',phone:'',city:'',otherCity:'',address:'',installation:'consult',note:'',invoice:false,company:'',tax:'',consent:false},errors:{},toastTimer:null};
function save(){try{localStorage.setItem('lgs-preview-v2',JSON.stringify({saved:state.saved,cart:state.cart,requests:state.requests}))}catch{}}
function go(route){state.scrolls[location.hash]=window.scrollY;if(location.hash.startsWith('#/product/')){const id=location.hash.split('/')[2].split('?')[0];state.productPreferences[id]={plan:state.plan,mode:state.mode}}if(route.startsWith('/product/')){const id=route.split('/')[2].split('?')[0],pref=state.productPreferences[id];state.plan=pref?.plan||36;state.mode=pref?.mode||'monthly'}if(route.startsWith('/product/')&&!location.hash.startsWith('#/checkout/')&&!location.hash.startsWith('#/subscribe/')&&!location.hash.startsWith('#/consult/')&&!location.hash.startsWith('#/product/')){state.previous=location.hash||'#/home';state.gallery=0}const h='#'+route;if(location.hash===h){render();return}location.hash=h}
function refresh(){const y=window.scrollY,focused=document.activeElement,key=['plan','mode','installation','form'].find(k=>focused?.dataset?.[k]!==undefined),selector=focused?.id?'#'+CSS.escape(focused.id):key?'[data-'+key+'="'+CSS.escape(focused.dataset[key])+'"]':null;render(true);if(selector)$(selector)?.focus({preventScroll:true});window.scrollTo(0,y)}
function toast(message){clearTimeout(state.toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;state.toastTimer=setTimeout(()=>$('#toast').hidden=true,2600)}
function header(){return `<header class="header"><button class="brand" data-go="/home" aria-label="LG Subscribe, trang chủ"><img src="${ASSETS.logo}" alt="LG"><span class="brand-name">Subscribe</span></button><div class="header-actions"><button class="icon-button" data-action="search" aria-label="Tìm sản phẩm">${icon('search')}</button><button class="icon-button" data-go="/cart" aria-label="Giỏ hàng${state.cart.length?', '+state.cart.length+' sản phẩm':''}">${icon('bag')}${state.cart.length?`<span class="counter">${state.cart.length}</span>`:''}</button></div></header>`}
function nav(active){return `<nav class="nav" aria-label="Điều hướng chính">${[['home','home','Trang chủ'],['products','grid','Sản phẩm'],['packages','package','Gói của tôi'],['account','user','Tài khoản']].map(([id,i,label])=>`<button class="nav-button" data-go="/${id}" ${active===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`).join('')}</nav>`}
function pageTop(title,desc='',back=null){return `<div class="page-top">${back?`<div class="back-heading"><button class="icon-button" data-go="${escape(back)}" aria-label="Quay lại">${icon('back')}</button><h1>${escape(title)}</h1></div>`:`<h1>${escape(title)}</h1>`}${desc?`<p>${escape(desc)}</p>`:''}</div>`}
const campaigns=[{title:'Nhẹ mỗi tháng.<br>Trọn tiện nghi.',desc:'Máy giặt LG AI DD',price:byId('washer').monthly[36],image:'washer',label:'AI DD · '+byId('washer').attributes.capacity,cta:'Khám phá máy giặt',route:'/product/washer',className:'',kicker:'Sống thảnh thơi cùng LG'},{title:'Màn hình lớn.<br>Niềm vui lớn.',desc:'TV LG QNED evo 86 inch',price:byId('tv').monthly[36],image:'tv',label:'QNED evo · 4K',cta:'Khám phá TV',route:'/product/tv',className:'promo-tv',kicker:'Nâng tầm giải trí tại nhà'},{title:'Không khí sạch.<br>Nhà an lành.',desc:'LG PuriCare 360 HIT',price:byId('air').monthly[36],image:'air',label:'PuriCare · '+byId('air').attributes.capacity,cta:'Xem máy lọc khí',route:'/product/air',className:'promo-air',kicker:'Chăm chút không gian sống'}];
function hero(){const c=campaigns[state.campaign];return `<section class="hero ${c.className}" aria-label="Chiến dịch ${state.campaign+1} trong 3"><div class="hero-content"><div class="eyebrow"><span class="brand-mark"></span>${c.kicker}</div><h1>${c.title}</h1><p class="hero-desc">${c.desc}</p><div class="hero-price"><small>Từ</small> ${money(c.price)}<small>/tháng*</small></div><button class="hero-cta" data-go="${c.route}">${c.cta}${icon('arrow')}</button><span class="hero-term">Gói 36 tháng</span></div><div class="hero-scene"><span class="hero-stage" aria-hidden="true"></span><img src="${ASSETS[c.image]}" alt="${escape(c.desc)}"><span class="hero-product-label">${c.label}</span></div><span class="hero-signature" aria-hidden="true">Life’s Good.</span></section>`}
function productCard(p){return `<article class="product-card"><div class="product-visual">${p.attributes.capacity?`<span class="product-tag">${escape(p.attributes.capacity)}</span>`:''}<button class="product-open" data-product="${p.id}" aria-label="Xem ${escape(p.name)}"><img src="${ASSETS[p.imageKey]}" alt="${escape(p.name)}" loading="lazy"></button>${p.imageIsIllustrative?'<span class="image-disclaimer">Hình minh họa</span>':''}<button class="heart-button" data-save="${p.id}" aria-pressed="${state.saved.includes(p.id)}" aria-label="${state.saved.includes(p.id)?'Bỏ lưu':'Lưu'} ${escape(p.name)}">${icon('heart')}</button></div><button class="product-copy" data-product="${p.id}" aria-label="Chi tiết ${escape(p.name)}, từ ${money(p.monthly[36])} mỗi tháng, gói 36 tháng"><h3>${escape(p.name)}</h3><p class="product-spec">${escape(p.attributes.style||p.subtitle)}</p><div class="model">${escape(p.model)}</div>${p.canRegister===false?'<p class="availability-label">'+escape(statusLabel(p))+'</p>':''}<div class="card-price-label">Từ / tháng</div><div class="price">${money(p.monthly[36])}</div><p class="term-note">36 tháng · Tổng ${money(p.monthly[36]*36)}</p><span class="card-link">Xem chi tiết ${icon('arrow')}</span></button><div class="product-card-actions"><button class="primary" data-buy="${p.id}" data-card-buy="true" aria-label="Mua ${escape(p.name)}" ${p.canRegister===false?'disabled':''}>${p.canRegister===false?'Tạm chưa nhận đơn':'Mua'} ${icon('arrow')}</button></div></article>`}
function home(){return `<main class="screen home-screen" id="main"><div class="hero-wrap"><div id="hero-slot">${hero()}</div><div class="campaign-controls"><div class="pagination" aria-label="Chọn banner">${campaigns.map((c,i)=>`<button class="dot-button" data-campaign="${i}" aria-label="Banner ${i+1}: ${c.desc}" aria-pressed="${state.campaign===i}"><span></span></button>`).join('')}</div><button class="text-button" data-action="campaign-info">Về LG Subscribe ${icon('arrow')}</button></div></div><div class="reassurance"><span>${icon('calendar')}12 / 24 / 36 tháng</span><span>${icon('tool')}Chăm sóc theo gói</span></div><section class="category-home"><div class="section-heading"><div><p class="section-kicker">Cho ngôi nhà bạn</p><h2>Tìm đúng thiết bị</h2></div><button class="text-button" data-action="category-picker" aria-haspopup="dialog">13 loại ${icon('grid')}</button></div><div class="category-grid">${CATEGORIES.slice(0,7).map(c=>`<button class="category-tile" data-category="${c.id}" aria-label="Xem ${escape(c.label)}"><span class="category-visual ${c.id}"><img src="${ASSETS[c.id]}" alt=""></span><span>${escape(c.shortLabel)}</span></button>`).join('')}<button class="category-tile" data-action="category-picker" aria-label="Xem tất cả loại sản phẩm"><span class="category-visual all">${icon('grid')}</span><span>Tất cả</span></button></div></section><section class="campaign-small"><div class="campaign-small-copy"><div class="eyebrow">Thêm thời gian cho bạn</div><h2>Bếp sạch.<br>Việc nhà nhẹ tênh.</h2><p>LG QuadWash · 14 bộ</p><button class="text-button" data-category="dish">Khám phá máy rửa bát ${icon('arrow')}</button></div><div class="small-stage"><img src="${ASSETS.dish}" alt="Máy rửa bát LG QuadWash"></div></section><section class="featured"><div class="section-heading"><div><p class="section-kicker">Bắt đầu từ điều bạn thích</p><h2>Gợi ý cho tổ ấm</h2></div><button class="text-button" data-category="all" aria-label="Xem tất cả sản phẩm">Tất cả ${icon('arrow')}</button></div><div class="product-grid">${['fridge','washer','dish','air'].map(id=>productCard(byId(id))).join('')}</div></section>${consultationPanel()}<section class="benefits"><p class="section-kicker">LG Subscribe</p><h2>Tiện nghi, theo cách của bạn.</h2><div class="benefit-grid"><div><span class="benefit-number">01</span><div><h3>Chọn thiết bị</h3><p>Tìm sản phẩm vừa nhu cầu.</p></div>${icon('grid')}</div><div><span class="benefit-number">02</span><div><h3>Chọn kỳ hạn</h3><p>Xem giá tháng và tổng chi phí.</p></div>${icon('calendar')}</div><div><span class="benefit-number">03</span><div><h3>Để LG đồng hành</h3><p>Mua sản phẩm và chọn giao lắp.</p></div>${icon('chat')}</div></div><button class="text-button" data-go="/support">Tìm hiểu cách mua hàng ${icon('arrow')}</button></section><p class="footnote">*Giá minh họa theo gói 36 tháng. Nội dung chiến dịch là ý tưởng cho bản xem trước.</p></main>${nav('home')}`}
function normalize(s){return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d')}
function filtered(filters=state.filters){let list=PRODUCTS.filter(p=>state.category==='all'||p.uiCategoryId===state.category);if(state.query.trim())list=list.filter(p=>normalize(p.name+' '+p.model+' '+p.subtitle+' '+(cat(p.uiCategoryId)?.label||'')).includes(normalize(state.query.trim())));list=list.filter(p=>(filters.budget==='all'||p.monthly[36]<=Number(filters.budget))&&(filters.capacity==='all'||p.attributes.capacity===filters.capacity)&&(filters.style==='all'||p.attributes.style===filters.style)&&(filters.maxWidth==='all'||(p.attributes.widthCm!==null&&p.attributes.widthCm<=Number(filters.maxWidth))));if(state.sort==='price-up')list.sort((a,b)=>a.monthly[36]-b.monthly[36]);if(state.sort==='price-down')list.sort((a,b)=>b.monthly[36]-a.monthly[36]);return list}
function countFilters(f=state.filters){return Object.values(f).filter(v=>v!=='all').length}
function resultMarkup(list){return list.length?`<div class="product-grid">${list.map(productCard).join('')}</div>`:`<div class="empty"><div class="empty-icon">${icon('search')}</div><h2>Chưa có sản phẩm phù hợp</h2><p>Thử tăng ngân sách hoặc bỏ bớt bộ lọc để xem thêm lựa chọn.</p><button class="primary" data-action="clear-filters">Xóa bộ lọc và tìm kiếm</button></div>`}
function activeFilterMarkup(){const f=state.filters;return Object.entries(f).filter(([,v])=>v!=='all').map(([key,value])=>`<button class="active-filter" data-remove-filter="${key}">${escape(key==='budget'?'Đến '+money(value)+'/tháng':key==='maxWidth'?'Rộng ≤ '+value+' cm':value)}${icon('close')}</button>`).join('')}
function catalog(saved=false){const list=saved?PRODUCTS.filter(p=>state.saved.includes(p.id)):filtered(),selected=cat(state.category);return `<main class="screen catalog-screen" id="main">${pageTop(saved?'Sản phẩm đã lưu':'Khám phá sản phẩm',saved?'Những lựa chọn bạn muốn xem lại.':'Thiết bị LG. Gói vừa nhu cầu.',saved?'/account':null)}${saved?'':`<div class="catalog-search">${icon('search')}<input id="product-search" type="search" placeholder="Tên sản phẩm hoặc mã model" value="${escape(state.query)}" aria-label="Tìm sản phẩm hoặc mã model"></div><div class="catalog-toolbar"><button class="category-switch" data-action="category-picker" aria-haspopup="dialog"><span>${selected?escape(selected.shortLabel):'Tất cả thiết bị'}</span>${icon('chevron')}</button><button class="toolbar-button" data-action="filter" aria-haspopup="dialog">${icon('filter')}Bộ lọc <span id="filter-count" class="filter-count" ${countFilters()?'':'hidden'}>${countFilters()}</span></button></div><div class="active-filters" id="active-filters">${activeFilterMarkup()}</div>`}<div class="results-line"><strong id="result-count" role="status" aria-live="polite">${list.length} sản phẩm${saved?' đã lưu':''}</strong>${saved?'<span>Gói 36 tháng</span>':`<select class="sort-select" id="product-sort" aria-label="Sắp xếp sản phẩm"><option value="recommended" ${state.sort==='recommended'?'selected':''}>Gợi ý cho bạn</option><option value="price-up" ${state.sort==='price-up'?'selected':''}>Giá tăng dần</option><option value="price-down" ${state.sort==='price-down'?'selected':''}>Giá giảm dần</option></select>`}</div><div class="catalog-products" id="catalog-results">${saved&&!list.length?`<div class="empty"><div class="empty-icon">${icon('heart')}</div><h2>Lưu lựa chọn bạn thích</h2><p>Chạm vào trái tim trên sản phẩm để xem lại ở đây.</p><button class="primary" data-go="/products">Khám phá sản phẩm</button></div>`:resultMarkup(list)}</div>${consultationPanel()}<p class="footnote">Giá theo gói 36 tháng, cần xác nhận khi mua. Một số hình ảnh minh họa dòng sản phẩm.</p></main>${nav(saved?'account':'products')}`}
function paintResults(){const list=filtered();$('#catalog-results').innerHTML=resultMarkup(list);$('#result-count').textContent=list.length+' sản phẩm';$('#active-filters').innerHTML=activeFilterMarkup();$('#filter-count').textContent=countFilters();$('#filter-count').hidden=!countFilters()}
function priceSummary(p){const monthly=state.mode==='monthly';return `<div class="plan-summary"><div class="summary-top"><div class="price">${money(monthly?p.monthly[state.plan]:p.buyPrice)}<small>${monthly?'mỗi tháng × '+state.plan+' tháng':'thanh toán một lần'}</small></div><span>${monthly?'Kỳ hạn bạn đã chọn':'Giá mua sản phẩm'}</span></div>${monthly?`<hr><div class="cost-row"><span>Tổng theo kỳ hạn</span><strong>${money(p.monthly[state.plan]*state.plan)}</strong></div><div class="cost-row"><span>Giá mua một lần</span><span>${money(p.buyPrice)}</span></div>`:''}<p class="term-note" style="margin-top:12px">Giá minh họa. Phí giao, lắp và dịch vụ được xác nhận trước khi ký hợp đồng.</p></div>`}
function miniProduct(p,term=state.plan,mode=state.mode){return `<div class="mini-product"><img src="${ASSETS[p.imageKey]}" alt="${escape(p.name)}"><div><h3>${escape(p.name)}</h3><p>${escape(p.model)} · ${mode==='monthly'?'Gói '+term+' tháng':'Mua một lần'}</p><div class="price">${money(mode==='monthly'?p.monthly[term]:p.buyPrice)}${mode==='monthly'?'<small> /tháng</small>':''}</div></div></div>`}
function detail(p){const gallery=p.galleryKeys.filter(k=>ASSETS[k]);const image=gallery[state.gallery]||gallery[0];return `<main class="screen has-dock" id="main">${pageTop(cat(p.uiCategoryId)?.label||'Sản phẩm','',state.previous.replace(/^#/,''))}<div class="detail-visual"><button class="heart-button" data-save="${p.id}" aria-pressed="${state.saved.includes(p.id)}" aria-label="${state.saved.includes(p.id)?'Bỏ lưu':'Lưu'} ${escape(p.name)}">${icon('heart')}</button><img id="detail-image" class="detail-main-image" src="${ASSETS[image]}" alt="${escape(p.name)}${state.gallery?' — hình '+(state.gallery+1):''}">${p.imageIsIllustrative?'<p class="gallery-caption">Hình minh họa dòng sản phẩm</p>':''}${gallery.length>1?`<div class="gallery-strip" aria-label="Hình ảnh sản phẩm">${gallery.map((key,i)=>`<button class="gallery-button" data-gallery="${i}" aria-pressed="${state.gallery===i}" aria-label="Hình ${i+1} của ${escape(p.name)}"><img src="${ASSETS[key]}" alt=""></button>`).join('')}</div>`:''}</div><section class="detail-copy"><div class="model">${escape(p.model)}</div><h1>${escape(p.name)}</h1><div class="spec-pills">${[...new Set([p.attributes.capacity,...p.subtitle.split(' · ')].filter(Boolean))].map(s=>`<span>${escape(s)}</span>`).join('')}</div>${p.canRegister===false?`<p class="availability-label" style="margin-top:13px">${escape(statusLabel(p))}</p><button class="text-button" data-go="/products">Chọn sản phẩm khác ${icon('arrow')}</button>`:''}</section><section class="plan-section"><div class="section-heading"><h2>Chọn cách thanh toán</h2></div><div class="segmented" aria-label="Cách thanh toán"><button data-mode="monthly" aria-pressed="${state.mode==='monthly'}">Theo tháng</button><button data-mode="buy" aria-pressed="${state.mode==='buy'}">Mua một lần</button></div>${state.mode==='monthly'?`<div class="term-grid" aria-label="Kỳ hạn thanh toán">${[12,24,36].map(t=>`<button class="term-option" data-plan="${t}" aria-pressed="${state.plan===t}"><strong>${t} tháng</strong><span><b>${money(p.monthly[t])}</b><small>/tháng</small></span></button>`).join('')}</div>`:''}${priceSummary(p)}</section>${consultationPanel(p)}${p.features.length?`<section class="service-card"><h2>Điểm nổi bật</h2>${p.features.map(f=>`<div class="feature-row">${icon('check')}<div><h3>${escape(f)}</h3></div></div>`).join('')}</section>`:''}<div class="accordion"><details><summary>Thông số & kích thước</summary><div class="answer"><table class="spec-table"><tbody>${[['Model',p.model],['Dung lượng / công suất',p.attributes.capacity||'Xác nhận khi tư vấn'],['Kích thước (R × C × S)',p.attributes.size||'Xác nhận khi tư vấn'],['Kiểu sản phẩm',p.attributes.style],['Màu sắc',p.attributes.color||'Xác nhận khi tư vấn'],['Công nghệ',p.attributes.technology||'Xác nhận khi tư vấn']].map(([a,b])=>`<tr><td>${a}</td><td>${escape(b)}</td></tr>`).join('')}</tbody></table></div></details><details><summary>Gói LG Subscribe gồm những gì?</summary><div class="answer">Gói theo tháng có sản phẩm và dịch vụ chăm sóc đi kèm. Nhân viên sẽ xác nhận lịch chăm sóc, phạm vi bảo hành, phí giao và lắp đặt của gói cụ thể trước khi hoàn tất đơn hàng.</div></details><details><summary>Mua sản phẩm như thế nào?</summary><div class="answer">Chọn cách thanh toán và bấm Mua. Điền thông tin người mua, nhu cầu giao lắp và kiểm tra đơn hàng. Nếu cần thêm thông tin, dùng phần Đăng ký tư vấn bên ngoài thông tin sản phẩm.</div></details></div><div class="pad"><button class="secondary" style="width:100%" data-add-cart="${p.id}" ${p.canRegister===false?'disabled':''}>${icon('bag')}Thêm vào giỏ hàng</button></div><p class="footnote" style="margin-top:18px">Thông tin và giá trong bản xem trước dùng để minh họa trải nghiệm.</p></main><div class="dock"><div class="dock-price"><div class="price ${(state.mode==='monthly'?p.monthly[state.plan]:p.buyPrice)>=100000000?'price-long':''}">${money(state.mode==='monthly'?p.monthly[state.plan]:p.buyPrice)}</div><small>${state.mode==='monthly'?'/tháng · '+state.plan+' tháng':'Thanh toán một lần'}</small></div><button class="primary" data-buy="${p.id}" ${p.canRegister===false?'disabled':''}>${p.canRegister===false?'Tạm chưa nhận đơn':'Mua'} ${icon('arrow')}</button></div>`}
let focusBeforeSheet=null;
function openSheet(title,content,footer=''){focusBeforeSheet=document.activeElement;$('#sheet-root').innerHTML=`<div class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><div class="sheet-handle"></div><div class="sheet-heading"><h2 id="sheet-title">${title}</h2><button class="icon-button" data-action="close-sheet" aria-label="Đóng">${icon('close')}</button></div><div class="sheet-content">${content}</div>${footer?`<div class="sheet-actions">${footer}</div>`:''}</div>`;$('#sheet-root').hidden=false;$('#app').inert=true;document.body.style.overflow='hidden';$('#sheet-root .icon-button').focus()}
function closeSheet(){if($('#sheet-root').hidden)return;$('#sheet-root').hidden=true;$('#sheet-root').innerHTML='';$('#app').inert=false;document.body.style.overflow='';if(focusBeforeSheet?.isConnected)focusBeforeSheet.focus()}
function categorySheet(){openSheet('Bạn đang tìm thiết bị nào?',`<p class="category-sheet-intro">Chọn loại sản phẩm, rồi lọc theo ngân sách và kích thước.</p><div class="category-picker-grid"><button class="category-pick ${state.category==='all'?'selected':''}" data-category="all" aria-pressed="${state.category==='all'}"><span class="category-pick-image">${icon('grid')}</span><span>Tất cả thiết bị<small>${PRODUCTS.length} sản phẩm</small></span>${icon('chevron')}</button>${CATEGORIES.map(c=>`<button class="category-pick ${state.category===c.id?'selected':''}" data-category="${c.id}" aria-pressed="${state.category===c.id}"><span class="category-pick-image"><img src="${ASSETS[c.id]}" alt=""></span><span>${escape(c.label)}<small>${PRODUCTS.filter(p=>p.uiCategoryId===c.id).length} sản phẩm</small></span>${icon('chevron')}</button>`).join('')}</div>`)}
function filterSheet(){state.draft={...state.filters};const categoryProducts=PRODUCTS.filter(p=>state.category==='all'||p.uiCategoryId===state.category), capacity=[...new Set(categoryProducts.map(p=>p.attributes.capacity).filter(Boolean))], styles=[...new Set(categoryProducts.map(p=>p.attributes.style).filter(Boolean))];const group=(key,opts)=>`<div class="filter-options">${opts.map(([v,l])=>`<button class="choice" data-filter-key="${key}" data-filter-value="${escape(v)}" aria-pressed="${state.draft[key]===v}">${escape(l)}</button>`).join('')}</div>`;openSheet('Lọc sản phẩm',`<div class="label">Ngân sách mỗi tháng</div><p class="sub-label">Giá theo gói 36 tháng, áp dụng cho toàn bộ danh sách.</p>${group('budget',[['all','Tất cả'],['500000','Đến 500.000đ'],['1000000','Đến 1.000.000đ'],['1500000','Đến 1.500.000đ']])}<div class="label">${escape(cat(state.category)?.filterLabel||'Dung lượng / công suất')}</div>${group('capacity',[['all','Tất cả'],...capacity.map(s=>[s,s])])}<div class="label">${state.category==='dish'?'Kiểu sản phẩm':'Loại sản phẩm'}</div>${group('style',[['all','Tất cả'],...styles.map(s=>[s,s])])}<div class="label">Chiều rộng sản phẩm</div>${group('maxWidth',[['all','Tất cả'],['60','Đến 60 cm'],['80','Đến 80 cm']])}<p class="sub-label" style="margin-top:12px">Sản phẩm chưa có số đo sẽ không xuất hiện khi lọc theo chiều rộng.</p>`,`<button class="secondary" data-action="reset-draft">Đặt lại</button><button class="primary" data-action="apply-filters" id="apply-filters">Xem ${filtered(state.draft).length} sản phẩm</button>`)}
function formField(key,label,type='text',placeholder='',hint=''){return `<div class="field ${state.errors[key]?'invalid':''}"><label for="form-${key}">${label}</label><input id="form-${key}" name="${key}" data-form="${key}" type="${type}" value="${escape(state.form[key])}" placeholder="${placeholder}" ${key==='phone'?'inputmode="tel" autocomplete="tel" maxlength="24"':key==='name'?'autocomplete="name"':key==='address'?'autocomplete="street-address"':''} ${state.errors[key]?'aria-invalid="true"':''} aria-describedby="error-${key}"><p class="error" id="error-${key}">${state.errors[key]||''}</p>${hint?`<p class="hint">${hint}</p>`:''}</div>`}
function checkout(p,step){const steps=['Thông tin','Giao & lắp','Xác nhận'];return `<main class="screen has-dock" id="main">${pageTop('Mua sản phẩm','',step>1?'/checkout/'+p.id+'?step='+(step-1):'/product/'+p.id)}<div class="stepper" aria-label="Tiến trình mua hàng">${steps.map((s,i)=>`<div class="step ${step===i+1?'active':step>i+1?'done':''}" ${step===i+1?'aria-current="step"':''}><span>${step>i+1?'✓':i+1}</span>${s}</div>`).join('')}</div>${miniProduct(p)}<div class="form-area">${step===1?`<h2>Thông tin người mua</h2><p>Nhập thông tin để xác nhận đơn hàng và giao lắp.</p>${formField('name','Họ và tên','text','Nhập họ và tên')}${formField('phone','Số điện thoại','tel','Nhập số điện thoại')}<div class="field ${state.errors.city?'invalid':''}"><label for="form-city">Tỉnh / Thành phố</label><select id="form-city" data-form="city" aria-describedby="error-city"><option value="">Chọn tỉnh / thành phố</option>${['TP. Hồ Chí Minh','Hà Nội','Đà Nẵng','Hải Phòng','Cần Thơ','Tỉnh / Thành phố khác'].map(c=>`<option ${state.form.city===c?'selected':''}>${c}</option>`).join('')}</select><p class="error" id="error-city">${state.errors.city||''}</p></div>${state.form.city==='Tỉnh / Thành phố khác'?formField('otherCity','Tên tỉnh / thành phố','text','Nhập tỉnh / thành phố'):''}<div class="form-info">${icon('shield')}<span>Thông tin dùng để xác nhận đơn hàng và khu vực giao lắp.</span></div>`:step===2?`<h2>Nhu cầu giao & lắp</h2><p>Chọn phương án thuận tiện cho bạn.</p>${[['consult','Tư vấn thời gian phù hợp','Trao đổi lịch và chi phí với nhân viên.','chat'],['install','Giao hàng và hỗ trợ lắp đặt','Xác nhận điều kiện lắp đặt tại địa chỉ của bạn.','tool']].map(([v,a,b,i])=>`<button class="installation-choice" data-installation="${v}" aria-pressed="${state.form.installation===v}">${icon(i)}<span><strong>${a}</strong><small>${b}</small></span>${state.form.installation===v?icon('check'):''}</button>`).join('')}<div style="margin-top:21px">${formField('address','Địa chỉ dự kiến (không bắt buộc)','text','Số nhà, đường, phường / xã')}</div><div class="field"><label for="form-note">Ghi chú (không bắt buộc)</label><textarea id="form-note" data-form="note" placeholder="Ví dụ: liên hệ sau 17:00">${escape(state.form.note)}</textarea></div><label class="consent"><input type="checkbox" data-form="invoice" ${state.form.invoice?'checked':''}><span>Tôi cần xuất hóa đơn công ty</span></label>${state.form.invoice?formField('company','Tên công ty (không bắt buộc)')+formField('tax','Mã số thuế (không bắt buộc)'):''}<div class="form-info">${icon('info')}<span>Nhân viên sẽ xác nhận phí giao, vật tư và lắp đặt trước khi hoàn tất đơn hàng.</span></div>`:`<h2>Kiểm tra đơn hàng</h2><p>Xem lại sản phẩm, gói thanh toán và thông tin giao lắp.</p><div class="review-block"><div class="review-heading"><h3>Thông tin liên hệ</h3><button data-go="/checkout/${p.id}?step=1">Sửa</button></div><p>${escape(state.form.name)}<br>${escape(state.form.phone)}<br>${escape(state.form.city==='Tỉnh / Thành phố khác'?state.form.otherCity:state.form.city)}</p></div><div class="review-block"><div class="review-heading"><h3>Giao & lắp</h3><button data-go="/checkout/${p.id}?step=2">Sửa</button></div><p>${state.form.installation==='install'?'Giao hàng và hỗ trợ lắp đặt':'Tư vấn lịch phù hợp'}${state.form.address?'<br>'+escape(state.form.address):''}${state.form.note?'<br>Ghi chú: '+escape(state.form.note):''}${state.form.invoice?'<br>Yêu cầu hóa đơn công ty'+(state.form.company?' · '+escape(state.form.company):'')+(state.form.tax?'<br>MST: '+escape(state.form.tax):''):''}</p></div>${priceSummary(p)}<label class="consent"><input type="checkbox" data-form="consent" ${state.form.consent?'checked':''}><span>Tôi đồng ý để LG liên hệ xác nhận đơn hàng và giao lắp. <button data-action="privacy">Xem cách sử dụng thông tin</button>.</span></label>${state.errors.consent?`<p class="error" style="color:var(--heritage)">${state.errors.consent}</p>`:''}<div class="form-info">${icon('info')}<span>Bản demo: chỉ tạo đơn hàng mẫu trên thiết bị, chưa xử lý thanh toán.</span></div>`}</div></main><div class="dock"><button class="primary" data-next-step="${step}" data-id="${p.id}">${step===3?'Xác nhận mua hàng':'Tiếp tục'}${icon('arrow')}</button></div>`}
function validateContact(){state.errors={};if(state.form.name.trim().length<2)state.errors.name='Vui lòng nhập họ và tên.';if(!/^0\d{9}$/.test(state.form.phone.replace(/[\s.()-]/g,'').replace(/^\+84/,'0')))state.errors.phone='Nhập số 10 chữ số hoặc số bắt đầu bằng +84.';if(!state.form.city)state.errors.city='Vui lòng chọn tỉnh / thành phố.';if(state.form.city==='Tỉnh / Thành phố khác'&&state.form.otherCity.trim().length<2)state.errors.otherCity='Vui lòng nhập tỉnh / thành phố.';return !Object.keys(state.errors).length}
function nextStep(p,step){if(!p||p.canRegister===false){toast('Sản phẩm hiện chưa nhận đơn hàng');go('/products');return}if(step===1&&!validateContact()){refresh();const key=Object.keys(state.errors)[0];$('#form-'+key)?.focus();return}state.errors={};if(step<3){go('/checkout/'+p.id+'?step='+(step+1));return}if(!validateContact()){go('/checkout/'+p.id+'?step=1');return}if(!state.form.consent){state.errors.consent='Đánh dấu đồng ý để xác nhận mua hàng.';refresh();$('[data-form="consent"]').focus();return}const request={kind:'purchase',ref:'LG-'+Date.now().toString().slice(-6),id:p.id,plan:state.plan,mode:state.mode,date:new Date().toISOString()};state.requests.unshift(request);state.cart=state.cart.filter(x=>x.id!==p.id);save();go('/success')}
function success(){const r=state.requests[0];if(!r)return packages();const p=byId(r.id);return `<main class="screen" id="main"><div class="success"><div class="success-burst">${icon('check')}</div><h1>Đã tạo đơn hàng mẫu</h1><p>Đơn hàng mẫu đã được ghi nhận.<br>Bạn có thể xem lại trong “Gói của tôi”.</p><div class="request-ref">${escape(r.ref)}</div><div class="review-block"><h3>${escape(p.name)}</h3><p>${r.mode==='monthly'?'Gói '+r.plan+' tháng · '+money(p.monthly[r.plan])+'/tháng':'Mua một lần · '+money(p.buyPrice)}</p><p>Tổng theo lựa chọn: ${money(r.mode==='monthly'?p.monthly[r.plan]*r.plan:p.buyPrice)}</p></div><div class="form-info">${icon('info')}<span>Chưa gửi yêu cầu thực tế, ký hợp đồng hoặc thanh toán. Đây là bản xem trước giao diện.</span></div><button class="primary" data-go="/packages">Xem đơn hàng của tôi</button><button class="text-button" style="justify-content:center;width:100%;margin-top:10px" data-go="/home">Về trang chủ ${icon('arrow')}</button></div></main>${nav('packages')}`}
function packages(){return `<main class="screen" id="main">${pageTop('Gói của tôi','Theo dõi đơn hàng và chăm sóc sản phẩm.')}<div class="segmented" style="margin:0 20px 24px"><button aria-pressed="true">Đơn hàng (${state.requests.length})</button><button data-action="active-packages" aria-pressed="false">Đang sử dụng (0)</button></div>${state.requests.length?state.requests.map(r=>{const p=byId(r.id);return `<article class="package-card">${miniProduct(p,r.plan,r.mode)}<div class="status-strip"><strong>Đơn hàng mẫu</strong><span>${escape(r.ref)}</span></div><button class="text-button" style="margin:4px 14px" data-request-detail="${escape(r.ref)}">Xem chi tiết ${icon('arrow')}</button></article>`}).join(''):`<div class="empty packages-empty"><div class="empty-icon">${icon('package')}</div><h2>Tiện nghi mới đang chờ bạn</h2><p>Chọn sản phẩm và gói phù hợp để bắt đầu.<br>Đơn hàng của bạn sẽ xuất hiện tại đây.</p><button class="primary" data-go="/products">Khám phá sản phẩm</button></div>`}<p class="footnote">Các đơn hàng mẫu được lưu trên thiết bị.</p></main>${nav('packages')}`}
function account(){return `<main class="screen" id="main"><div class="profile-box"><div class="avatar">${icon('user')}</div><div><h1>Xin chào bạn</h1><p>Cùng LG chăm sóc ngôi nhà bạn.</p></div></div><div class="menu-list"><button class="menu-row" data-go="/saved">${icon('heart')}Sản phẩm đã lưu <span class="saved-count">${state.saved.length}</span>${icon('chevron')}</button><button class="menu-row" data-action="consultation-history">${icon('chat')}Yêu cầu tư vấn <span class="saved-count">${state.consultations.length}</span>${icon('chevron')}</button><button class="menu-row" data-go="/packages">${icon('package')}Đơn hàng của tôi${icon('chevron')}</button><button class="menu-row" data-go="/support">${icon('chat')}Hỏi đáp & hỗ trợ${icon('chevron')}</button><button class="menu-row" data-action="privacy">${icon('shield')}Quyền riêng tư${icon('chevron')}</button><button class="menu-row" data-action="about">${icon('info')}Về LG Subscribe${icon('chevron')}</button></div><div class="support-intro"><h2>Life’s Good.</h2><p>Sản phẩm bạn thích.<br>Gói thanh toán phù hợp với bạn.</p><button class="text-button" data-go="/products">Tìm lựa chọn của bạn ${icon('arrow')}</button></div><p class="footnote">Bản xem trước MiniApp · Nội dung tiếng Việt.</p></main>${nav('account')}`}
function support(){return `<main class="screen" id="main">${pageTop('LG luôn sẵn sàng hỗ trợ','', '/account')}${consultationPanel()}<section class="help-card"><h3>Mua sản phẩm</h3><p>Chọn thiết bị, gói thanh toán và bấm Mua. Sau đó điền thông tin người mua, nhu cầu giao lắp và xác nhận đơn hàng.</p></section><section class="help-card"><h3>Tư vấn trước khi mua</h3><p>Để lại họ tên, số điện thoại và email. Yêu cầu được ghi nhận kèm mã model để nhân viên tư vấn đúng sản phẩm.</p></section><section class="help-card"><h3>Chọn gói phù hợp</h3><p>Xem giá theo kỳ hạn 12, 24 hoặc 36 tháng và tổng chi phí trước khi mua.</p></section><div class="accordion"><details><summary>LG Subscribe là gì?</summary><div class="answer">LG Subscribe là lựa chọn thanh toán theo tháng cho sản phẩm LG đủ điều kiện, cùng dịch vụ chăm sóc theo gói. Kỳ hạn, dịch vụ và chi phí cụ thể được xác nhận trước khi hoàn tất đơn hàng.</div></details><details><summary>Yêu cầu tư vấn gồm thông tin gì?</summary><div class="answer">Họ tên, số điện thoại, email và mã model sản phẩm bạn quan tâm. Bạn cũng có thể gọi hotline 1800 1503.</div></details><details><summary>Phí lắp đặt được tính thế nào?</summary><div class="answer">Chi phí tùy loại sản phẩm, địa chỉ và yêu cầu vật tư. Nhân viên xác nhận chi phí trước khi hoàn tất đơn hàng.</div></details></div></main>${nav('account')}`}
function cart(){return `<main class="screen" id="main">${pageTop('Giỏ hàng','Chọn sản phẩm bạn muốn mua.','/home')}${state.cart.length?state.cart.map(r=>{const p=byId(r.id);return `<article class="cart-row"><button class="icon-button" data-remove-cart="${p.id}" aria-label="Bỏ ${escape(p.name)} khỏi giỏ">${icon('close')}</button>${miniProduct(p,r.plan,r.mode)}<button class="secondary" data-cart-register="${p.id}" ${p.canRegister===false?'disabled':''}>Mua sản phẩm này ${icon('arrow')}</button></article>`}).join(''):`<div class="empty packages-empty"><div class="empty-icon">${icon('bag')}</div><h2>Giỏ hàng đang trống</h2><p>Thêm sản phẩm để lưu lại kỳ hạn bạn đã chọn.</p><button class="primary" data-go="/products">Xem sản phẩm</button></div>`}${state.cart.length?'<div class="request-small">Mỗi sản phẩm được tạo đơn hàng riêng theo gói và nhu cầu giao lắp đã chọn.</div>':''}</main>${nav('products')}`}
function render(preserve=false){closeSheet();const hash=location.hash.slice(1)||window.LG_DEFAULT_ROUTE||'/home';const [path,query]=hash.split('?'), seg=path.split('/').filter(Boolean), page=seg[0]||'home';let view='';if(page==='home')view=home();else if(page==='products'){const params=new URLSearchParams(query);if(params.has('category'))state.category=cat(params.get('category'))?params.get('category'):'all';view=catalog()}else if(page==='saved')view=catalog(true);else if(page==='product')view=byId(seg[1])?detail(byId(seg[1])):`<main class="screen">${pageTop('Không tìm thấy sản phẩm')}<div class="empty"><p>Sản phẩm này chưa có trong danh mục.</p><button class="primary" data-go="/products">Xem danh mục</button></div></main>${nav('products')}`;else if((page==='checkout'||page==='subscribe'))view=byId(seg[1])&&byId(seg[1]).canRegister!==false?checkout(byId(seg[1]),Math.min(3,Math.max(1,Number(new URLSearchParams(query).get('step'))||1))):`<main class="screen">${pageTop('Hiện chưa nhận đơn hàng')}<div class="empty"><p>Sản phẩm này chưa sẵn sàng mua.</p><button class="primary" data-go="/products">Chọn sản phẩm khác</button></div></main>${nav('products')}`;else if(page==='consult')view=consultationPage(byId(seg[1]));else if(page==='success')view=success();else if(page==='packages')view=packages();else if(page==='account')view=account();else if(page==='support')view=support();else if(page==='cart')view=cart();else view=home();$('#app').innerHTML=header()+view;if(state.pendingFocus){$(state.pendingFocus)?.focus({preventScroll:true});state.pendingFocus=null;}const rail=$('.category-scroll'),active=rail?.querySelector('.pill.active');if(active)rail.scrollLeft=active.offsetLeft-rail.offsetLeft-(rail.clientWidth-active.clientWidth)/2;document.title='LG Subscribe · '+({home:'Trang chủ',products:'Sản phẩm',product:byId(seg[1])?.name||'Sản phẩm',checkout:'Mua sản phẩm',subscribe:'Mua sản phẩm',consult:'Đăng ký tư vấn',packages:'Gói của tôi',account:'Tài khoản',saved:'Đã lưu',success:'Đơn hàng mẫu',cart:'Giỏ hàng',support:'Hỗ trợ'}[page]||'MiniApp');if(!preserve)window.scrollTo(0,state.scrolls[location.hash]||0)}

function hotline(){return `<a class="hotline-link" href="tel:18001503" aria-label="Gọi hotline 1800 1503">${icon('phone')}Gọi 1800 1503</a>`}
function consultationPanel(p=null){return `<section class="consultation-panel" aria-label="Tư vấn sản phẩm"><div class="eyebrow">LG luôn sẵn sàng hỗ trợ</div><h2>Cần thêm thông tin trước khi mua?</h2><p>Để lại thông tin để được tư vấn${p?' về sản phẩm bạn đang xem':'. Hoặc gọi trực tiếp hotline LG'}.</p><div class="consultation-actions"><button class="secondary" data-consult="${p?.id||''}">${icon('chat')}Đăng ký tư vấn</button>${hotline()}</div>${p?`<small class="model-context">Model tư vấn: <strong>${escape(p.model)}</strong></small>`:''}</section>`}
function startConsultation(id=''){if(state.consultation.submitting)return;state.consultBack=location.hash.replace(/^#/,'')||'/products';state.consultation.productId=byId(id)?.id||'';state.consultation.errors={};state.consultation.success=null;const route='/consult'+(id?'/'+id:'');state.scrolls['#'+route]=0;go(route)}
function consultationField(key,label,type,autocomplete){const c=state.consultation,error=c.errors[key];return `<div class="field ${error?'invalid':''}"><label for="consult-${key}">${label} <span aria-hidden="true">*</span></label><input id="consult-${key}" name="${key}" type="${type}" data-consult-field="${key}" value="${escape(c[key])}" autocomplete="${autocomplete}" required ${key==='phone'?'inputmode="tel" maxlength="24"':key==='email'?'maxlength="254"':'maxlength="100"'} aria-describedby="consult-error-${key}" ${error?'aria-invalid="true"':''}><p class="error" id="consult-error-${key}">${escape(error||'')}</p></div>`}
function consultationPage(scopedProduct=null){const c=state.consultation;if(scopedProduct&&c.productId!==scopedProduct.id){c.productId=scopedProduct.id;c.success=null;c.errors={}}const p=byId(c.productId);if(c.success){const r=c.success;return `<main class="screen consultation-screen" id="main"><div class="consultation-confirmation"><div class="success-burst">${icon('check')}</div><h1>${r.status==='submitted'?'Đã gửi yêu cầu tư vấn':'Đã ghi nhận yêu cầu mẫu'}</h1><p>${r.status==='submitted'?'LG sẽ liên hệ theo thông tin bạn đã để lại.':'Yêu cầu tư vấn đã được lưu trên thiết bị trong bản demo.'}</p><div class="request-ref">${escape(r.ref)}</div><div class="review-block"><h2>Sản phẩm cần tư vấn</h2><p>${escape(byId(r.productId)?.name||r.model)}<br>Model: <strong>${escape(r.model)}</strong></p></div>${hotline()}<button class="secondary" data-go="/product/${r.productId}">Xem lại sản phẩm ${icon('arrow')}</button><button class="text-button" data-go="/account">Yêu cầu tư vấn của tôi ${icon('arrow')}</button></div></main>${nav('account')}`}
return `<main class="screen consultation-screen" id="main">${pageTop('Đăng ký tư vấn','Để lại thông tin, LG sẽ tư vấn sản phẩm bạn quan tâm.',state.consultBack)}${p?`<div class="consult-product-context"><img src="${ASSETS[p.imageKey]}" alt=""><div><h2>${escape(p.name)}</h2><p class="model">Model: ${escape(p.model)}</p></div></div>`:''}<form id="consultation-form" class="consultation-form" novalidate>${scopedProduct?'':`<div class="field ${c.errors.productId?'invalid':''}"><label for="consult-productId">Sản phẩm quan tâm <span aria-hidden="true">*</span></label><select id="consult-productId" data-consult-field="productId" required aria-describedby="consult-error-productId" ${c.errors.productId?'aria-invalid="true"':''}><option value="">Chọn sản phẩm / mã model</option>${CATEGORIES.map(cat=>`<optgroup label="${escape(cat.label)}">${PRODUCTS.filter(p=>p.uiCategoryId===cat.id).map(p=>`<option value="${p.id}" ${p.id===c.productId?'selected':''}>${escape(p.model)} · ${escape(p.name)}</option>`).join('')}</optgroup>`).join('')}</select><p class="error" id="consult-error-productId">${escape(c.errors.productId||'')}</p></div>`}${consultationField('name','Họ và tên','text','name')}${consultationField('phone','Số điện thoại','tel','tel')}${consultationField('email','Email','email','email')}<p class="consultation-note">Yêu cầu tự kèm mã model${p?' <strong>'+escape(p.model)+'</strong>':' sản phẩm đã chọn'}. LG dùng thông tin để liên hệ tư vấn cho bạn.</p><button class="primary" type="submit" ${c.submitting?'disabled aria-busy="true"':''}>${c.submitting?'Đang ghi nhận…':'Gửi yêu cầu tư vấn'} ${icon('arrow')}</button><div class="consultation-feedback" role="status" aria-live="polite" ${c.errors.submit?'data-state="error"':''}>${escape(c.errors.submit||'')}</div>${hotline()}<p class="consultation-demo-note">${window.LG_CONSULTATION_ENDPOINT?'Yêu cầu sẽ được gửi đến hệ thống tư vấn.':'Bản demo: yêu cầu được lưu trên thiết bị.'}</p></form></main>${nav('account')}`}
function validateConsultation(){const c=state.consultation;c.errors={};if(!byId(c.productId))c.errors.productId='Vui lòng chọn sản phẩm cần tư vấn.';if(c.name.trim().length<2)c.errors.name='Vui lòng nhập họ và tên.';const phone=c.phone.replace(/[\s.()-]/g,'').replace(/^\+84/,'0');if(!/^0\d{9}$/.test(phone))c.errors.phone='Nhập số 10 chữ số hoặc số bắt đầu bằng +84.';if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.email.trim()))c.errors.email='Vui lòng nhập email hợp lệ.';return !Object.keys(c.errors).length}
async function submitConsultation(){const c=state.consultation;if(c.submitting)return;if(!validateConsultation()){refresh();const first=Object.keys(c.errors)[0];$('#consult-'+first)?.focus();return}const p=byId(c.productId),record={ref:'LG-TV-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,6).toUpperCase(),productId:p.id,model:p.model,name:c.name.trim(),phone:c.phone.replace(/[\s.()-]/g,'').replace(/^\+84/,'0'),email:c.email.trim(),createdAt:new Date().toISOString(),status:window.LG_CONSULTATION_ENDPOINT?'submitted':'local-demo'};c.submitting=true;refresh();try{if(window.LG_CONSULTATION_ENDPOINT){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),20000);try{const response=await fetch(window.LG_CONSULTATION_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(record),signal:controller.signal});if(!response.ok)throw new Error('server');}finally{clearTimeout(timeout);}}const records=[record,...state.consultations];try{localStorage.setItem('lgs-consultations-v1',JSON.stringify(records));}catch(error){if(record.status==='local-demo')throw new Error('storage');}state.consultations=records;c.success=record;c.errors={};window.dispatchEvent(new CustomEvent('lg:consultation-created',{detail:{...record}}));}catch(error){c.errors.submit=error.message==='storage'?'Thiết bị chưa lưu được yêu cầu. Vui lòng thử lại hoặc gọi 1800 1503.':'Chưa gửi được yêu cầu. Thông tin vẫn được giữ lại; vui lòng thử lại hoặc gọi 1800 1503.';}finally{c.submitting=false;if(location.hash.startsWith('#/consult'))refresh();}}
function consultationHistory(){openSheet('Yêu cầu tư vấn của tôi',state.consultations.length?state.consultations.map(r=>`<article class="review-block"><h3>${escape(byId(r.productId)?.name||r.model)}</h3><p>Model: <strong>${escape(r.model)}</strong><br>Mã yêu cầu: ${escape(r.ref)}<br>${r.status==='submitted'?'Đã gửi đến hệ thống tư vấn':'Đã ghi nhận mẫu trên thiết bị'}</p><button class="text-button" data-go="/product/${r.productId}">Xem sản phẩm ${icon('arrow')}</button></article>`).join(''):`<div class="empty"><h2>Chưa có yêu cầu tư vấn</h2><p>Chọn sản phẩm và để lại thông tin để được hỗ trợ.</p><button class="primary" data-consult="">Đăng ký tư vấn</button>${hotline()}</div>`)}

function startPurchase(id,fromCard=false){if(!byId(id)||byId(id).canRegister===false){toast('Sản phẩm hiện chưa nhận đơn hàng');return}if(fromCard){const pref=state.productPreferences[id];state.plan=pref?.plan||36;state.mode=pref?.mode||'monthly';state.previous=location.hash;}state.errors={};state.form.consent=false;state.scrolls['#/checkout/'+id+'?step=1']=0;go('/checkout/'+id+'?step=1')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
if(b.dataset.go){go(b.dataset.go);return}
if(b.dataset.product){state.previous=location.hash;state.gallery=0;go('/product/'+b.dataset.product);return}
if(b.dataset.category){const next=b.dataset.category;if(next!==state.category){state.filters={budget:'all',capacity:'all',style:'all',maxWidth:'all'};state.query=''}state.category=next;state.pendingFocus='.category-switch';state.scrolls['#/products?category='+next]=0;go('/products?category='+next);return}
if(b.dataset.save){const id=b.dataset.save,selected=state.saved.includes(id);state.saved=selected?state.saved.filter(x=>x!==id):[...state.saved,id];save();document.querySelectorAll('[data-save="'+id+'"]').forEach(el=>{el.setAttribute('aria-pressed',!selected);el.setAttribute('aria-label',(!selected?'Bỏ lưu ':'Lưu ')+byId(id).name)});if(location.hash.startsWith('#/saved'))refresh();toast(selected?'Đã bỏ lưu sản phẩm':'Đã lưu trong Tài khoản → Sản phẩm đã lưu');return}
if(b.dataset.campaign!==undefined){state.campaign=Number(b.dataset.campaign);$('#hero-slot').innerHTML=hero();document.querySelectorAll('[data-campaign]').forEach(el=>el.setAttribute('aria-pressed',Number(el.dataset.campaign)===state.campaign));return}
if(b.dataset.plan){state.plan=Number(b.dataset.plan);refresh();return}
if(b.dataset.mode){state.mode=b.dataset.mode;refresh();return}
if(b.dataset.gallery!==undefined){state.gallery=Number(b.dataset.gallery);const p=byId(location.hash.split('/')[2]?.split('?')[0]);$('#detail-image').src=ASSETS[p.galleryKeys.filter(k=>ASSETS[k])[state.gallery]];$('#detail-image').alt=p.name+' — hình '+(state.gallery+1);document.querySelectorAll('[data-gallery]').forEach(el=>el.setAttribute('aria-pressed',Number(el.dataset.gallery)===state.gallery));return}
if(b.dataset.buy){startPurchase(b.dataset.buy,b.dataset.cardBuy==='true');return}
if(b.dataset.consult!==undefined){startConsultation(b.dataset.consult);return}
if(b.dataset.addCart){if(byId(b.dataset.addCart)?.canRegister===false)return;const entry={id:b.dataset.addCart,plan:state.plan,mode:state.mode};state.cart=state.cart.filter(x=>x.id!==entry.id);state.cart.push(entry);save();refresh();toast('Đã thêm sản phẩm và kỳ hạn vào giỏ hàng');return}
if(b.dataset.removeCart){state.cart=state.cart.filter(x=>x.id!==b.dataset.removeCart);save();refresh();return}
if(b.dataset.cartRegister){const r=state.cart.find(x=>x.id===b.dataset.cartRegister);state.plan=r.plan;state.mode=r.mode;startPurchase(r.id);return}
if(b.dataset.nextStep){b.disabled=true;nextStep(byId(b.dataset.id),Number(b.dataset.nextStep));return}
if(b.dataset.installation){state.form.installation=b.dataset.installation;refresh();return}
if(b.dataset.filterKey){state.draft[b.dataset.filterKey]=b.dataset.filterValue;document.querySelectorAll('[data-filter-key="'+b.dataset.filterKey+'"]').forEach(el=>el.setAttribute('aria-pressed',el.dataset.filterValue===state.draft[b.dataset.filterKey]));$('#apply-filters').textContent='Xem '+filtered(state.draft).length+' sản phẩm';return}
if(b.dataset.removeFilter){state.filters[b.dataset.removeFilter]='all';paintResults();return}
if(b.dataset.requestDetail){const r=state.requests.find(x=>x.ref===b.dataset.requestDetail),p=byId(r.id);openSheet('Chi tiết đơn hàng mẫu',`<div class="answer"><h3>${escape(p.name)}</h3><p>Mã: ${escape(r.ref)}<br>${r.mode==='monthly'?'Gói '+r.plan+' tháng<br>'+money(p.monthly[r.plan])+'/tháng<br>Tổng '+money(p.monthly[r.plan]*r.plan):'Mua một lần: '+money(p.buyPrice)}</p><p>Trạng thái: đơn hàng mẫu được lưu trên thiết bị. Chưa có hợp đồng, lịch giao lắp hoặc thanh toán thực tế.</p></div>`);return}
const action=b.dataset.action;if(action==='category-picker')categorySheet();else if(action==='close-sheet')closeSheet();else if(action==='filter')filterSheet();else if(action==='search'){state.category='all';state.query='';state.filters={budget:'all',capacity:'all',style:'all',maxWidth:'all'};go('/products');setTimeout(()=>$('#product-search')?.focus(),80)}else if(action==='clear-filters'){state.filters={budget:'all',capacity:'all',style:'all',maxWidth:'all'};state.query='';refresh()}else if(action==='apply-filters'){state.filters={...state.draft};closeSheet();paintResults()}else if(action==='reset-draft'){state.draft={budget:'all',capacity:'all',style:'all',maxWidth:'all'};document.querySelectorAll('[data-filter-key]').forEach(el=>el.setAttribute('aria-pressed',el.dataset.filterValue==='all'));$('#apply-filters').textContent='Xem '+filtered(state.draft).length+' sản phẩm'}else if(action==='more')openSheet('LG Subscribe',`<button class="menu-row" data-go="/support">${icon('chat')}Hỏi đáp & hỗ trợ${icon('chevron')}</button><button class="menu-row" data-action="about">${icon('info')}Về LG Subscribe${icon('chevron')}</button><button class="menu-row" data-action="privacy">${icon('shield')}Quyền riêng tư${icon('chevron')}</button>`);else if(action==='about'||action==='campaign-info')openSheet('Tiện nghi theo cách của bạn',`<div class="answer"><h3>Chọn sản phẩm. Chọn gói.</h3><p>LG Subscribe giúp bạn khám phá các sản phẩm LG và lựa chọn kỳ hạn thanh toán phù hợp. Dịch vụ chăm sóc, điều kiện và giá cuối cùng được xác nhận khi đăng ký.</p><h3>Khám phá ngay trong MiniApp</h3><p>Chọn loại sản phẩm, lọc theo giá và kích thước, xem tổng chi phí, rồi mua sản phẩm. Hoặc để lại thông tin tại phần tư vấn riêng.</p><p>Banner và giá trong bản xem trước dùng để minh họa thiết kế.</p></div><button class="primary" data-go="/products">Khám phá sản phẩm ${icon('arrow')}</button>`);else if(action==='privacy')openSheet('Cách sử dụng thông tin',`<div class="answer"><p>Thông tin người mua được dùng để xác nhận đơn hàng và nhu cầu giao lắp. Khi gửi yêu cầu tư vấn, họ tên, số điện thoại, email và mã model giúp nhân viên liên hệ đúng nhu cầu.</p><p>Bản demo chưa cấu hình API: yêu cầu tư vấn gồm thông tin liên hệ và model được lưu trên thiết bị. Thông tin người mua ở form mua hàng chỉ tồn tại khi trang đang mở; đơn hàng mẫu lưu mã sản phẩm và lựa chọn gói.</p><p>Chính sách quyền riêng tư và đơn vị xử lý dữ liệu cần được xác nhận trước khi đưa MiniApp vào sử dụng.</p></div>`);else if(action==='active-packages')openSheet('Gói đang sử dụng',`<div class="empty" style="padding:12px 0 8px"><div class="empty-icon">${icon('package')}</div><h2>Bạn chưa có gói đang sử dụng</h2><p>Gói đã kích hoạt sẽ xuất hiện tại đây cùng lịch thanh toán và chăm sóc.</p><button class="primary" data-go="/products">Chọn sản phẩm</button></div>`);else if(action==='ask-advice')startConsultation('');else if(action==='consultation-history')consultationHistory();
});
document.addEventListener('input',e=>{if(e.target.dataset.consultField){const key=e.target.dataset.consultField;state.consultation[key]=e.target.value;delete state.consultation.errors[key];const error=$('#consult-error-'+key);if(error)error.textContent='';e.target.closest('.field')?.classList.remove('invalid');e.target.removeAttribute('aria-invalid');}if(e.target.id==='product-search'){state.query=e.target.value;paintResults()}if(e.target.dataset.form){state.form[e.target.dataset.form]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(state.errors[e.target.dataset.form]){delete state.errors[e.target.dataset.form];const er=$('#error-'+e.target.dataset.form);if(er)er.textContent='';e.target.closest('.field')?.classList.remove('invalid');e.target.removeAttribute('aria-invalid')}}});
document.addEventListener('change',e=>{if(e.target.dataset.consultField==='productId'){state.consultation.productId=e.target.value;state.consultation.errors={};refresh();}if(e.target.id==='product-sort'){state.sort=e.target.value;paintResults()}if(e.target.dataset.form==='invoice'){state.form.invoice=e.target.checked;refresh()}if(e.target.dataset.form==='city'){refresh()}});
document.addEventListener('submit',e=>{if(e.target.id==='consultation-form'){e.preventDefault();submitConsultation();}});
$('#sheet-root').addEventListener('click',e=>{if(e.target.id==='sheet-root')closeSheet()});
document.addEventListener('keydown',e=>{if($('#sheet-root').hidden)return;if(e.key==='Escape'){e.preventDefault();closeSheet()}if(e.key==='Tab'){const f=[...$('#sheet-root').querySelectorAll('button,a,input,select,textarea,[tabindex="0"]')].filter(x=>!x.disabled&&!x.hidden),first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
let touchX=0;document.addEventListener('touchstart',e=>{if(e.target.closest('.hero'))touchX=e.touches[0].clientX},{passive:true});document.addEventListener('touchend',e=>{if(!e.target.closest('.hero'))return;const delta=e.changedTouches[0].clientX-touchX;if(Math.abs(delta)>45){state.campaign=(state.campaign+(delta<0?1:2))%3;$('#hero-slot').innerHTML=hero();document.querySelectorAll('[data-campaign]').forEach(el=>el.setAttribute('aria-pressed',Number(el.dataset.campaign)===state.campaign))}},{passive:true});
window.addEventListener('hashchange',()=>render());
if(!location.hash)location.hash=window.LG_DEFAULT_ROUTE||'/home';else render();
}());
